package dev.felipe.warbands.blueprint;

import dev.felipe.warbands.Warbands;
import dev.felipe.warbands.town.Age;
import net.minecraft.core.BlockPos;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.Identifier;
import org.jspecify.annotations.Nullable;

/**
 * A buildable structure. Sizes must match the structure files in
 * {@code data/warbands/structure/}, generated by {@code tools/gen_structures.py}.
 * Footprints are odd squares so they rotate in place around their center.
 * In the unrotated structure the entrance is on the south side (z = max).
 * Everything except the Town Center goes near your own Town Center and pays stone from its stockpile.
 */
public enum Blueprint {
	TOWN_CENTER("town_center", 11, 16, new BlockPos(5, 1, 5), Age.VILLAGE, 0, null),
	HOUSE("house", 7, 9, new BlockPos(4, 1, 3), Age.VILLAGE, 30, "no_town_center"),
	BARRACKS("barracks", 9, 11, new BlockPos(4, 1, 4), Age.FEUDAL, 100, "barracks_needs_town"),
	ARCHERY_RANGE("archery_range", 9, 6, new BlockPos(4, 1, 4), Age.FEUDAL, 100, "archery_needs_town"),
	BLACKSMITH("blacksmith", 7, 11, new BlockPos(3, 1, 3), Age.FEUDAL, 150, "blacksmith_needs_town"),
	STABLE("stable", 9, 10, new BlockPos(4, 1, 4), Age.CASTLE, 150, "stable_needs_town"),
	WATCH_TOWER("watch_tower", 5, 10, new BlockPos(2, 1, 2), Age.CASTLE, 200, "tower_needs_town"),
	SIEGE_WORKSHOP("siege_workshop", 9, 10, new BlockPos(4, 1, 4), Age.CASTLE, 150, "siege_needs_town");

	private final String name;
	private final int size;
	private final int height;
	private final BlockPos core;
	private final Age requiredAge;
	private final int stoneCost;
	private final @Nullable String needsTownKey;

	Blueprint(String name, int size, int height, BlockPos core, Age requiredAge, int stoneCost, @Nullable String needsTownKey) {
		this.name = name;
		this.size = size;
		this.height = height;
		this.core = core;
		this.requiredAge = requiredAge;
		this.stoneCost = stoneCost;
		this.needsTownKey = needsTownKey;
	}

	/** The blueprint called {@code name}, or null. */
	public static @Nullable Blueprint byName(String name) {
		for (Blueprint blueprint : values()) {
			if (blueprint.name.equals(name)) {
				return blueprint;
			}
		}
		return null;
	}

	public String getName() {
		return name;
	}

	public Identifier structureId() {
		return Warbands.id(name);
	}

	/** Width and depth of the footprint. */
	public int size() {
		return size;
	}

	public int half() {
		return size / 2;
	}

	/** Height including the foundation layer, which replaces the clicked ground level. */
	public int height() {
		return height;
	}

	/** Position of the core block (Town Center / Hearth) inside the unrotated structure. */
	public BlockPos core() {
		return core;
	}

	/** The age the nearby Town Center must have reached. */
	public Age requiredAge() {
		return requiredAge;
	}

	/** Stone taken from the nearby Town Center's stockpile when this is built. */
	public int stoneCost() {
		return stoneCost;
	}

	/** True for everything that must be built within 64 blocks of its owner's Town Center. */
	public boolean needsTown() {
		return needsTownKey != null;
	}

	/** "Must be built within 64 blocks of your Town Center", worded for this building. */
	public Component needsTownMessage() {
		return Component.translatable("message.warbands." + needsTownKey);
	}
}
